import type { CliCommandResult } from './envelope';

const ENTRY_COMMANDS = new Set(['open', 'variants.start', 'reference.fetch']);
const NOTICE_TIMEOUT_MS = 1500;

export const withReferenceOnboarding = async (
  result: CliCommandResult,
): Promise<CliCommandResult> => {
  if (!result.envelope.ok || !ENTRY_COMMANDS.has(result.envelope.command))
    return result;
  const data = result.envelope.data;
  if (!data || typeof data !== 'object' || Array.isArray(data)) return result;
  try {
    const { getConfigManager } = await import('../services/ConfigManager');
    if (!getConfigManager().isAuthenticated()) return result;
    const [{ findHub }, { currentLibraryRoot }] = await Promise.all([
      import('../library/HubClient'),
      import('../services/ProjectLibrary'),
    ]);
    const hub = await findHub(currentLibraryRoot());
    if (!hub) return result;
    const response = await fetch(
      `${hub.url}/api/library/profile/onboarding/notices`,
      {
        method: 'POST',
        headers: { Authorization: `Bearer ${hub.token}` },
        signal: AbortSignal.timeout(NOTICE_TIMEOUT_MS),
      },
    );
    if (!response.ok) return result;
    const body: unknown = await response.json();
    if (
      !body ||
      typeof body !== 'object' ||
      !('notice' in body) ||
      !body.notice
    )
      return result;
    return {
      ...result,
      envelope: {
        ...result.envelope,
        data: { ...data, referenceOnboarding: body.notice },
      },
    };
  } catch {
    return result;
  }
};
